import { PostCard, type Post } from "march/ui"

// bir kedinin gönderisi: fotoğrafa çift dokununca büyük kalp yerine pati çıkar, beğeni turuncu olur
const SUNSET = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42mP4WSz2xmMmQ43VWzlpbwAsKgV3rhVt4wAAAABJRU5ErkJggg=="

export function CatPost() {
  let $post: Post = {
    id: "cat", author: { name: "Pamuk 🐈", handle: "pamuk.kedi" }, time: new Date(Date.now() - 7 * 60_000),
    text: "Güneşli pencere kenarı benim. Tartışmaya kapalıdır. 😼", media: [{ src: SUNSET, alt: "Pencerede gün batımı" }],
    likes: 99, comments: 12,
  }
  return <PostCard post={$post} bigHeart={<span sx={{ text: "2xl" }}>🐾</span>} likeColor="brand-orange"
    onLike={(on) => $post = { ...$post, liked: on, likes: $post.likes + (on ? 1 : -1) }} />
}

import { PostCard, toast, confirm, type Post } from "march/ui"
import { link, flag, eyeOff } from "march/icons"

// bir kulübün duyurusu: beğeni ve paylaşım sayıları iyimser güncellenir, yorumlar ve fotoğraflar açılır,
// ⋯ menüsünde bağlantıyı kopyala, gizle ve (onaylı) bildir
const PNG = (p: string) => `data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42m${p}AAAAABJRU5ErkJggg==`

export function ClubAnnouncement() {
  let $post: Post = {
    id: "run-42", author: { name: "HADİ Koşu Kulübü", handle: "hadi.kosu", verified: true }, time: new Date(Date.now() - 18 * 60_000),
    place: "Sahil yolu", likes: 1284, comments: 46, shares: 12,
    text: "Pazar sabahı sahil koşusu tamamlandı! 🧡 Yeni katılan herkese hoş geldiniz; tempo grubu 6:30'da, yürüyüş grubu 7:00'de buluşuyor. Gelecek hafta rota orman yoluna taşınıyor, ayrıntılar etkinlik sayfasında.",
    media: [
      { src: PNG("Ow2PuDb+lLBlm/Gz+LxQAthgZP+C/Xcg"), alt: "Deniz kıyısı" },
      { src: PNG("PY/f2C0tE4BrFUE5FgXQAtngULJa1nqA"), alt: "Orman yolu" },
      { src: PNG("P4+6zr9yQbhuXdvwz1GgE6ZgdD1tcTig"), alt: "Şafak" },
    ],
  }
  let $hidden = false
  const patch = (p: Partial<Post>) => { $post = { ...$post, ...p } }
  return $hidden ? <p sx={{ color: "muted" }}>Gönderi gizlendi.</p> : <PostCard post={$post}
    onLike={(on) => patch({ liked: on, likes: $post.likes + (on ? 1 : -1) })}
    onComment={() => toast(`${$post.comments} yorum açılır`)}
    onShare={() => { patch({ shares: ($post.shares ?? 0) + 1 }); toast("Bağlantı paylaşıldı") }}
    onOpenMedia={(i) => toast(`${i + 1}. fotoğraf açılır`)}
    onAuthor={() => toast("Kulübün profili açılır")}
    menu={[
      { label: "Bağlantıyı kopyala", icon: link, onSelect: () => toast("Kopyalandı") },
      { label: "Gizle", icon: eyeOff, onSelect: () => $hidden = true },
      "-",
      { label: "Bildir", icon: flag, danger: true, onSelect: async () => { if (await confirm("Bu gönderi bildirilsin mi?")) toast("Bildirildi") } },
    ]} />
}

import { PostCard, Card, Segmented, type Post } from "march/ui"
import { zap, send, settings, star, mapPin } from "march/icons"

// PostCard'ın bütün özellikleri: gönderi (erişimci), beğen / yorum / paylaş / fotoğraf / yazar olayları, ⋯ menüsü,
// görünüm, metin satırı (clamp), çift dokunuşla beğeni, kendi metinler, avatar, kendi zaman biçimi, kendi ikonlar,
// büyük kalp, beğeni rengi, "tüm yorumlar" satırı ve sınıf; altta koyu zeminde sade bir ikinci kart
const PNG = (p: string) => `data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42m${p}AAAAABJRU5ErkJggg==`

export function PostCardLab() {
  let $post: Post = {
    id: "lab", author: { name: "Fotoğraf Atölyesi", handle: "foto.atolye", verified: true }, time: new Date(2026, 10, 18, 9, 5),
    place: "Kadıköy", likes: 41, comments: 8, shares: 2,
    text: "Bu hafta analog banyo yaptık. Sonuçlar beklediğimizden iyi çıktı; karanlık oda turu cumartesi yine var, yer ayırtmayı unutmayın. Ekipman bizden, film sizden.",
    media: [{ src: PNG("OQk/Y21GtkeLWZg19cCwAXQQNaq9+sQQ"), alt: "Gece şehir" }, { src: PNG("P4+6xrSzAnQ4Up/7/PxwExlAbyzjJBwg"), alt: "Kahve" }],
  }
  let $log = "-"
  let $variant = "card"
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Segmented aria-label="Görünüm" options={[{ value: "card", label: "Kart" }, { value: "flat", label: "Düz" }]} bind:value={$variant} />
      <span sx={{ text: "sm", color: "muted" }}>{$log}</span>
    </div>
    <PostCard class="lab-post" post={() => $post} variant={() => $variant as "card"} clamp={2} doubleTapLike
      onLike={(on, p) => { $post = { ...p, liked: on, likes: p.likes + (on ? 1 : -1) }; $log = on ? "beğenildi" : "beğeni geri alındı" }}
      onComment={() => $log = "yorumlar"} onShare={() => { $post = { ...$post, shares: ($post.shares ?? 0) + 1 }; $log = "paylaşıldı" }}
      onOpenMedia={(i) => $log = `fotoğraf ${i + 1}`} onAuthor={(p) => $log = `yazar: ${p.author.name}`}
      menu={[{ label: "Kaydet", icon: star, onSelect: () => $log = "kaydedildi" }]}
      labels={{ like: "Beğen", more: "devamı", options: "Gönderi seçenekleri", viewAll: (n) => `${n} yorumun hepsi`, comments: (n) => `${n} yorum`, share: (n) => `${n} paylaşım` }}
      avatar time={(t) => new Date(t).toLocaleDateString("tr-TR", { day: "numeric", month: "long" })}
      verifiedIcon="✔" placeIcon={mapPin} commentIcon={zap} shareIcon={send} menuIcon={settings}
      bigHeart={<span sx={{ text: "2xl" }}>💜</span>} likeColor="brand-purple" viewAll />
    <Card m:theme="night">
      <PostCard post={{ id: "plain", author: { name: "Kitap Kulübü" }, time: Date.now() - 3_600_000, text: "Ayın kitabı oylamada.", likes: 5 }}
        variant="flat" avatar={false} time={false} viewAll={false} verifiedIcon={false} bigHeart={false} />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { PostCardLab } from "./PostCardLab.tsx"

// PostCardLab'in testleri: kaydedince Testler sekmesinde çalışır
test("Beğen'e basınca onLike sayıyı bir artırır ve düğme basılı durur", async () => {
  const s = renderTest(() => <PostCardLab />)
  const like = await s.click("Beğen")
  expect(s.sees("beğenildi")).toBe(true)
  expect(like.getAttribute("aria-pressed")).toBe("true")
  expect(s.sees("42")).toBe(true)
})

test("kendi metinler: tüm yorumlar satırı ve paylaşım düğmesinin adı", async () => {
  const s = renderTest(() => <PostCardLab />)
  await s.click("8 yorumun hepsi")
  expect(s.sees("yorumlar")).toBe(true)
  await s.click("2 paylaşım")
  expect(s.sees("paylaşıldı")).toBe(true)
  expect(s.find("3 paylaşım")).not.toBe(null)
})

test("yazara basınca onAuthor çalışır", async () => {
  const s = renderTest(() => <PostCardLab />)
  await s.click("Fotoğraf Atölyesi")
  expect(s.sees("yazar: Fotoğraf Atölyesi")).toBe(true)
})

test("ikinci kartta avatar, zaman ve tüm yorumlar satırı yok", () => {
  const s = renderTest(() => <PostCardLab />)
  expect(s.sees("Ayın kitabı oylamada.")).toBe(true)
  expect(s.all(".m-post").length).toBe(2)
  expect(s.all(".m-post")[1]?.querySelector(".m-avatar")).toBe(null)
})
